/** A80 member home: the server supplies public metadata, never a saved key value. */
export interface MemberHomePageInput {
  readonly name: string;
  readonly email: string;
  readonly publicId: string;
  readonly referralUrl: string;
  readonly membership: { readonly label: string; readonly note: string };
  readonly connection: { readonly linked: boolean | null; readonly startUrl: string };
  readonly startUrl: string;
  readonly devices: readonly { readonly name: string; readonly kind: string;
    readonly lastUsed: string }[] | null;
  /** Per-response CSP nonce generated by the route owner. */
  readonly nonce: string;
}

function html(value: string): string {
  return value.replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]!);
}

function href(value: string): string {
  try {
    const url = new URL(value, 'https://elanous.ai');
    if (url.protocol !== 'https:' && url.protocol !== 'http:') return '#';
    return html(value);
  } catch { return '#'; }
}

/** Return standalone HTML for the signed-in elanous.ai page. The caller sets the session and CSP headers. */
export function renderMemberHomePage(input: MemberHomePageInput): string {
  const devices = input.devices === null
    ? '<p class="empty">연결 기기 상태를 아직 확인하지 못했어요.</p>'
    : input.devices.length === 0
    ? '<p class="empty">연결된 기기가 없어요. 이 기기를 연결해 시작하세요.</p>'
    : `<ul class="rows">${input.devices.map((device) => `<li><span><strong>${html(device.name)}</strong><small>${html(device.kind)} · ${html(device.lastUsed)}</small></span></li>`).join('')}</ul>`;
  const primaryLabel = input.connection.linked === true ? '엘라누스 시작하기'
    : input.connection.linked === false ? '이 기기 연결' : '연결 상태 확인하기';
  const primaryUrl = input.connection.linked === true ? input.startUrl : input.connection.startUrl;
  const status = input.connection.linked === true ? '이 기기를 엘라누스에 연결했어요'
    : input.connection.linked === false ? '이 기기를 연결하면 바로 시작할 수 있어요' : '연결 상태를 아직 확인하지 못했어요';
  const nonce = html(input.nonce);
  const page = `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>내 계정 · Elanous</title>
<style nonce="${nonce}">:root{color-scheme:light;--ink:#192e35;--muted:#526971;--line:#d9e4e2;--surface:#f7faf8;--accent:#087866}*{box-sizing:border-box}body{margin:0;background:#fff;color:var(--ink);font:16px/1.55 system-ui,-apple-system,"Apple SD Gothic Neo",sans-serif}button,a{font:inherit}button{cursor:pointer}a{color:inherit}.shell{max-width:920px;margin:auto;padding:0 20px 72px}header{height:72px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}.brand{font-weight:750;letter-spacing:-.04em;font-size:24px;text-decoration:none}.signed{font-size:14px;color:var(--muted)}main{display:grid;gap:22px;padding-top:38px}h1{font-size:clamp(28px,5vw,42px);line-height:1.2;letter-spacing:-.04em;margin:0 0 8px}h2{font-size:20px;margin:0 0 14px;letter-spacing:-.025em}p{margin:0}.lead{color:var(--muted);margin-bottom:24px}.card{border:1px solid var(--line);border-radius:20px;padding:24px;background:var(--surface)}.hero{background:#e5f3ed;border:0;padding:32px}.primary{display:inline-block;background:var(--accent);color:#fff;border:0;border-radius:10px;padding:12px 18px;text-decoration:none;font-weight:700;min-height:48px}.field{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:12px 0;border-top:1px solid var(--line)}.field:first-of-type{border-top:0}.field span,.rows li span:first-child{min-width:0;overflow-wrap:anywhere}.field small,.rows small,.hint,.empty{display:block;color:var(--muted);font-size:14px}.quiet{background:#fff;border:1px solid #a9c4bc;border-radius:9px;padding:8px 11px;min-height:40px;white-space:nowrap}.danger{color:#9b3232}.rows{list-style:none;padding:0;margin:0}.rows li{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:12px 0;border-top:1px solid var(--line)}.actions{display:flex;gap:7px;flex-wrap:wrap}details{border-top:1px solid var(--line);padding-top:16px}summary{cursor:pointer;font-weight:700}output{display:block;min-height:24px;color:var(--accent);margin-top:10px}.secret{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:12px}.secret code{overflow-wrap:anywhere;background:#fff;padding:10px;border-radius:8px}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid #095bdb;outline-offset:3px}@media(max-width:600px){header{height:62px}.shell{padding:0 16px 48px}main{padding-top:24px;gap:14px}.card{padding:20px}.hero{padding:25px}.field,.rows li{align-items:flex-start;flex-direction:column}.field button,.rows button{width:100%}.actions{width:100%}}</style></head>
<body><div class="shell"><header><a class="brand" href="${href(input.startUrl)}">elanous</a><span class="signed">로그인됨 · ${html(input.name)}</span></header><main>
<section class="card hero" aria-labelledby="welcome"><h1 id="welcome">엘라누스에 오신 걸 환영해요</h1><p class="lead">${status}</p><a class="primary" href="${href(primaryUrl)}">${primaryLabel}</a></section>
<section class="card" aria-labelledby="telegram-connect"><h2 id="telegram-connect">텔레그램 연결</h2><p class="hint">이 계정과 텔레그램 대화방을 연결하세요. 연결 코드는 10분 동안 한 번만 사용할 수 있어요.</p><button type="button" class="quiet" id="telegram-issue">연결 코드 받기</button><div id="telegram-instructions" hidden><p class="hint">텔레그램에서 엘라누스 봇과 개인 대화를 열고 아래 명령을 보내세요. 그룹 대화에는 코드를 보내지 마세요.</p><div class="secret"><code id="telegram-command"></code><button type="button" class="quiet" id="telegram-copy">명령 복사</button></div><p class="hint" id="telegram-expiry"></p></div><output id="telegram-feedback" role="status" aria-live="polite"></output></section>
<section class="card" aria-labelledby="account"><h2 id="account">내 계정</h2><div class="field"><span>이름<strong>${html(input.name)}</strong></span></div><div class="field"><span>이메일<strong>${html(input.email)}</strong></span></div><div class="field"><span>내 회원 아이디<strong id="public-id">${html(input.publicId)}</strong></span><button type="button" class="quiet" data-copy="public-id">아이디 복사</button></div></section>
<section class="card" aria-labelledby="referral"><h2 id="referral">내 추천 링크</h2><div class="field"><span id="referral-url">${html(input.referralUrl)}</span><button type="button" class="quiet" data-copy="referral-url">내 추천 링크 복사</button></div></section>
<section class="card" aria-labelledby="devices"><h2 id="devices">연결된 기기</h2>${devices}<p class="hint"><a href="${href(input.connection.startUrl)}">이 기기 연결</a></p></section>
<section class="card" aria-labelledby="membership"><h2 id="membership">내 멤버십</h2><strong>${html(input.membership.label)}</strong><p class="hint">${html(input.membership.note)}</p></section>
<output id="feedback" role="status" aria-live="polite"></output></main></div>
<script nonce="${nonce}">(function(){
const out=document.getElementById('feedback');
let active=true;
const telegramIssue=document.getElementById('telegram-issue');
const telegramCopy=document.getElementById('telegram-copy');
const telegramCommand=document.getElementById('telegram-command');
const telegramInstructions=document.getElementById('telegram-instructions');
const telegramExpiry=document.getElementById('telegram-expiry');
const telegramFeedback=document.getElementById('telegram-feedback');
let telegramGeneration=0;
let telegramDeadline=0;
let telegramTimer;
function clearTelegramCode(){
  telegramGeneration++;
  telegramDeadline=0;
  if(telegramTimer)window.clearInterval(telegramTimer);
  telegramTimer=undefined;
  telegramCommand.textContent='';
  telegramInstructions.hidden=true;
  telegramCopy.disabled=true;
}
function refreshTelegramExpiry(){
  const seconds=Math.max(0,Math.ceil((telegramDeadline-Date.now())/1000));
  if(!seconds){clearTelegramCode();telegramFeedback.textContent='코드가 만료됐어요. 새 코드를 받으세요.';return}
  telegramExpiry.textContent='남은 시간 '+Math.floor(seconds/60)+'분 '+String(seconds%60).padStart(2,'0')+'초';
}
async function issueTelegramCode(){
  clearTelegramCode();
  const generation=telegramGeneration;
  telegramIssue.disabled=true;
  telegramFeedback.textContent='연결 코드를 발급하고 있어요.';
  const requestStartedAt=Date.now();
  try{
    const response=await fetch('/v1/telegram/member-enrollment',{method:'POST',credentials:'same-origin',headers:{'content-type':'application/json'},body:'{}',cache:'no-store'});
    if(!active||generation!==telegramGeneration)return;
    if(response.status===401){telegramFeedback.textContent='로그인이 만료됐어요. 다시 로그인해 주세요.';return}
    if(!response.ok){telegramFeedback.textContent='코드를 발급하지 못했어요. 잠시 뒤 다시 시도해 주세요.';return}
    const payload=await response.json();
    if(!active||generation!==telegramGeneration)return;
    const code=payload&&typeof payload.code==='string'?payload.code:'';
    const lifetime=payload&&payload.expiresInSeconds===600?600:0;
    if(!/^[0-9a-f]{32}$/.test(code)||!lifetime){
      telegramFeedback.textContent='코드 응답을 확인할 수 없어요. 다시 시도해 주세요.';return
    }
    const deadline=requestStartedAt+lifetime*1000;
    if(Date.now()>=deadline){telegramFeedback.textContent='코드가 만료됐어요. 새 코드를 받으세요.';return}
    telegramCommand.textContent='/connect '+code;
    telegramInstructions.hidden=false;
    telegramCopy.disabled=false;
    telegramDeadline=deadline;
    telegramFeedback.textContent='코드를 받았어요. 본인만 볼 수 있는 봇 개인 대화에 보내세요.';
    refreshTelegramExpiry();
    telegramTimer=window.setInterval(refreshTelegramExpiry,1000);
  }catch{
    if(active&&generation===telegramGeneration)telegramFeedback.textContent='연결할 수 없어요. 네트워크를 확인한 뒤 다시 시도해 주세요.';
  }finally{if(active&&generation===telegramGeneration)telegramIssue.disabled=false}
}
telegramIssue.addEventListener('click',function(){if(active&&!telegramIssue.disabled)void issueTelegramCode()});
telegramCopy.addEventListener('click',function(){
  if(!active||telegramCopy.disabled||!telegramDeadline||Date.now()>=telegramDeadline){clearTelegramCode();return}
  void navigator.clipboard.writeText(telegramCommand.textContent).then(function(){if(active)telegramFeedback.textContent='명령을 복사했어요. 봇 개인 대화에 붙여넣으세요.'}).catch(function(){if(active)telegramFeedback.textContent='복사할 수 없어요. 명령을 길게 눌러 복사해 주세요.'});
});
async function copy(id){
  const value=document.getElementById(id)?.textContent||'';
  try{await navigator.clipboard.writeText(value);if(active)out.textContent=id==='referral-url'?'추천 링크를 복사했어요':'회원 아이디를 복사했어요'}
  catch{if(active)out.textContent='복사할 수 없어요. 내용을 길게 눌러 복사해 주세요.'}
}
document.addEventListener('click',function(event){
  const target=event.target.closest('button[data-copy]');
  if(active&&target)void copy(target.dataset.copy);
});
window.addEventListener('pagehide',function(){active=false;clearTelegramCode();telegramIssue.disabled=false});
window.addEventListener('pageshow',function(){active=true});
})();</script></body></html>`;
  return page.replace('</style></head>', '.field strong{display:block;margin-top:3px}.signed{min-width:0;max-width:48%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}#referral-url{max-width:100%;overflow-wrap:anywhere;word-break:break-word}</style></head>');
}
